let previewRequest=0,liveTimer=null;
function bitcoinPanel(){blockSettings(s);const settings=s.bitcoin;
 $('bitcoinControls').innerHTML=`<div class="section-label">LE BLOC DEVIENT MATIÈRE</div><p class="tip">Même bloc + même configuration = mêmes tracés. Les dates sont en UTC.</p><label>Passerelle ord (aperçu uniquement)<input id="gateway" type="url" value="https://ordinals.com"></label><div class="two-cols"><label>Bloc à prévisualiser<input id="blockHeight" type="number" min="0" step="1" value="${currentBlock.height}"></label><button id="loadBlock">Charger</button></div><div class="preset-row"><button id="prevBlock">←</button><button id="nextBlock">→</button><button id="latestBlock">Dernier bloc</button><button id="genesisBlock">Genesis</button></div><label class="check"><input id="liveBlocks" type="checkbox"> Suivre les nouveaux blocs</label><label class="check"><input id="simulateBlocks" type="checkbox"> Simulation hors ligne (sans données Bitcoin réelles)</label><p id="blockInfo" class="tip" role="status"></p><div class="section-label">PARAMÈTRES VIVANTS</div><label class="check"><input id="blockSeed" type="checkbox" ${settings.seed?'checked':''}> Faire évoluer la seed avec le bloc</label><label class="check"><input id="blockPhase" type="checkbox" ${settings.phase?'checked':''}> Faire évoluer la phase avec le bloc</label><p class="tip">Cochez les paramètres qui changent. Les autres conservent leur valeur dans Réglages. La phase fait évoluer Flow, Type, Optical et Superformula. La seed pilote notamment Cellular et Isogrid. Min et max restent dans les limites du moteur.</p><div id="blockRules"></div><div class="section-label">TEXTES BITCOIN</div><p class="tip">Dans Affiche ou Type Playground, insérez :<br><code>{height} {date} {time}<br>{transactions} {total_fee}<br>{average_fee} {median_fee}<br>{fee_rate} {hash}</code><br>Frais en satoshis ; taux en sat/vB. Une donnée absente affiche N/A.</p><button id="bitcoinPoster" class="wide-button">Ajouter une affiche Bitcoin</button><p class="tip">L’export contient le moteur, la configuration et les contours des polices utilisées. Il suit automatiquement le bloc courant toutes les 30 secondes, via ordinals.com en local ou sur le web, et via le serveur Ordinals après inscription.</p>`;
 $('loadBlock').onclick=()=>previewBlock(Number($('blockHeight').value));$('prevBlock').onclick=()=>previewBlock(Math.max(0,currentBlock.height-1));$('nextBlock').onclick=()=>previewBlock(currentBlock.height+1);$('latestBlock').onclick=()=>previewBlock('latest');$('genesisBlock').onclick=()=>{previewRequest++;currentBlock={...GENESIS};render();updateBlockInfo('Bloc Genesis · données embarquées')};
 $('blockSeed').onchange=e=>{blockSettings(s).seed=e.target.checked;render()};$('blockPhase').onchange=e=>{blockSettings(s).phase=e.target.checked;render()};
 $('liveBlocks').onchange=e=>{clearInterval(liveTimer);if(e.target.checked){$('simulateBlocks').checked=false;previewBlock('latest');liveTimer=setInterval(()=>previewBlock('latest'),30000)}};
 $('simulateBlocks').onchange=()=>{clearInterval(liveTimer);$('liveBlocks').checked=false};
 $('bitcoinPoster').onclick=()=>{s.poster.enabled=true;s.poster.effect='overlay';s.poster.blocks=[{...blockDefaults,text:'BLOCK\n{height}',size:25,x:8,y:18,font:'bebas',weight:.3},{...blockDefaults,text:'{date} / {time}\n{transactions} TRANSACTIONS\nFEES {total_fee} SAT',size:3,x:8,y:76,tracking:.3,leading:1.8,weight:.18,font:'grotesk'}];posterControls();render();toast('Textes Bitcoin ajoutés au mode Affiche')};
 renderRules();updateBlockInfo('Bloc Genesis disponible hors ligne');
}
function renderRules(){if(!$('blockRules'))return;const settings=blockSettings(s),rules=settings.rules[s.engine]??={};$('blockRules').replaceChildren();for(const [key,label,min,max,step]of ruleSpecs(s)){const rule=rules[key]??={enabled:false,min,max};const row=document.createElement('div');row.className='block-rule';row.innerHTML=`<label class="check"><input type="checkbox" ${rule.enabled?'checked':''}>${label}</label><div class="two-cols"><label>Min<input type="number" min="${min}" max="${max}" step="${step}" value="${rule.min}"></label><label>Max<input type="number" min="${min}" max="${max}" step="${step}" value="${rule.max}"></label></div>`;const [check,low,high]=row.querySelectorAll('input');const change=()=>{const a=Number(low.value),b=Number(high.value);if(low.value===''||high.value===''||!Number.isFinite(a)||!Number.isFinite(b)||a<min||b>max||a>b||Math.ceil((a-min)/step-1e-8)>Math.floor((b-min)/step+1e-8)){low.setCustomValidity('Limites invalides');low.reportValidity();return}low.setCustomValidity('');Object.assign(rule,{enabled:check.checked,min:a,max:b});render()};check.onchange=low.onchange=high.onchange=change;$('blockRules').append(row)}}
function updateBlockInfo(message=''){if(!$('blockInfo'))return;$('blockHeight').value=currentBlock.height;$('blockInfo').textContent=(message?message+' · ':'')+(currentBlock.simulated?'SIMULATION':'BLOC '+currentBlock.height)+' · '+resolveText('{date} {time} · {transactions} TX · {total_fee} SAT',currentBlock);$('status').textContent=(currentBlock.simulated?'SIMULATION ':'BLOC ')+currentBlock.height;}
async function previewBlock(query){const request=++previewRequest;try{if($('simulateBlocks')?.checked&&query!=='latest'){if(!Number.isSafeInteger(query)||query<0)throw Error('Numéro invalide');currentBlock={height:query,simulated:true};render();updateBlockInfo();return}updateBlockInfo('Chargement…');const url=new URL($('gateway').value);if(!['https:','http:'].includes(url.protocol))throw Error('Passerelle HTTP(S) requise');const block=await readBlock(url.href.replace(/\/$/,''),query);if(request!==previewRequest)return;currentBlock=block;render();updateBlockInfo('Données récursives vérifiées')}catch(e){if(request!==previewRequest)return;updateBlockInfo('Échec réseau : aperçu précédent conservé');toast(e.message+' — vérifiez la passerelle et son accès CORS.')}}
function safeJSON(value){return JSON.stringify(value).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029')}
function exportHTML(){normalizeState();if(currentBlock.simulated)throw Error('Chargez un bloc réel ou Genesis avant l’export.');effectiveState(s,currentBlock);if(!hasBlockEvolution(s))throw Error('Activez une variation de seed, de phase ou de paramètre pour créer une œuvre vivante.');
 const families=new Set(s.poster.enabled?s.poster.blocks.filter(b=>b.visible).map(b=>b.font):[]);if(s.engine==='type')families.add(s.params.font);const fonts=Object.fromEntries([...families].filter(f=>VECTOR_FONTS[f]).map(f=>[f,VECTOR_FONTS[f]]));
 const bundle='const VECTOR_FONTS='+safeJSON(fonts)+';\n'+['typography.js','poster.js','geometry-engines.js','core.js','bitcoin.js'].map(n=>EXPORT_SOURCES[n]).join('\n');
 const boot=`s=${safeJSON(s)};currentBlock=${safeJSON(currentBlock)};
 const paint=()=>{document.getElementById('work').innerHTML=artworkSVG();document.body.style.background={white:'#f2f0e9',kraft:'#c4a579',black:'#191e21'}[s.paper];};
 paint();let busy=false;async function refresh(){if(busy)return;busy=true;try{const b=await readLiveBlock();if(b.hash!==currentBlock.hash){const previous=currentBlock;currentBlock=b;try{paint()}catch(error){currentBlock=previous;throw error}}document.getElementById('connection').textContent='';document.title='ORDINALS · BLOCK '+currentBlock.height;}catch(e){document.getElementById('connection').textContent='Connexion Ordinals indisponible · bloc '+currentBlock.height+' conservé · nouvelle tentative automatique';document.getElementById('connection').title=e.message;}finally{busy=false}}refresh();setInterval(refresh,30000);addEventListener('online',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});`;
 return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ORDINALS Studio</title><style>html,body{margin:0;width:100%;height:100%;overflow:hidden}#work{width:100%;height:100%;display:grid;place-items:center}svg{width:100%;height:100%;max-height:100vh}#connection{position:fixed;bottom:6px;left:8px;font:10px monospace;color:#888}</style></head><body><main id="work"></main><span id="connection" role="status"></span><script type="application/json" id="font-licenses">'+safeJSON(EXPORT_SOURCES.licenses)+'</script><script>'+ (bundle+'\n'+boot).replace(/<\/script/gi,'<\\/script')+'</script></body></html>';
}
function initBitcoin(){bitcoinPanel();const baseControls=controls;controls=function(){baseControls();renderRules();if($('blockSeed'))$('blockSeed').checked=blockSettings(s).seed;if($('blockPhase'))$('blockPhase').checked=blockSettings(s).phase};const baseRender=render;render=function(){baseRender();updateBlockInfo()};$('export').onclick=()=>{try{const html=exportHTML(),blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ORDINALS-${s.engine}-${s.seed}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('HTML autonome exporté · '+Math.ceil(blob.size/1024)+' Ko')}catch(e){toast(e.message)}};}
